-- Conceptos de equipo.xlsx que faltaban en dodo-2 (pestañas 04 a 17). Ejecutar después de 20261102120000_aperturas_categorias.sql.
-- Repetible: no toca conceptos ya cargados, ni sus estados, costos o responsables.
-- La pestaña 11 (resumen de contactos, 37 piezas) sustituye a la 09, que detalla los mismos contactos por altura y equipo.
begin;
do $$
declare p uuid;n integer;
