 -- La sucursal cambió de nombre ("Dodo Lopez Mateos (Dodo-2)"); se busca por "dodo-2" dentro del nombre.
 select count(*),min(x.id::text)::uuid into n,p from public.apertura_proyectos x join public.sucursales s on s.id=x.sucursal_id where lower(s.nombre) like '%dodo-2%';
 if n<>1 then raise exception 'Se esperaba una apertura de Dodo-2 y hay %.',n;end if;
