commit;
select 'CARGA OK' resultado,coalesce(i.categoria,'sin categoría') categoria,count(*) conceptos
from public.apertura_items i join public.apertura_proyectos p on p.id=i.proyecto_id join public.sucursales s on s.id=p.sucursal_id
where lower(s.nombre) like '%dodo-2%' and i.tipo in ('equipo','referencia') group by i.categoria order by i.categoria;
